# Dragonspire Gym 1F — the Dusk Spire. Platforms float over a black void; floor switches raise bridges.
# Stepping into the void drops you back to the entrance. Bridge flags: p3b_dg_b1..b3 (persist).
map dragonspire_gym
name "Dragonspire Gym"
location "Dragonspire City"
music gym_dusk
environment building
indoor
tags gym powerspot

legend
@ gym_wall_dusk
d gym_floor_dusk
r gym_floor_dusk_rune
G statue_dragon
P pillar_dusk
l lamp_dusk
* void
z puzzle_switch
U stairs_in_up
R rug_mat
end

